-- Sakhi V3 additive foundation migration.
-- Safe to run after the existing 20260909 migrations. It does not drop learner data.

-- V3 profile/session metadata used by the fixed six-month learning plan.
alter table learner_profiles add column if not exists settings jsonb not null default '{}'::jsonb;
alter table learner_profiles add column if not exists plan_state jsonb not null default '{}'::jsonb;
alter table learner_profiles add column if not exists weekly_report_enabled boolean not null default false;
alter table learner_profiles add column if not exists weekly_report_email text;

alter table learning_sessions add column if not exists plan_day_id text;
alter table learning_sessions add column if not exists week integer;
alter table learning_sessions add column if not exists planned_blocks jsonb not null default '[]'::jsonb;
alter table learning_sessions add column if not exists status text;
alter table learning_sessions add column if not exists last_activity_at timestamptz;

-- A versioned JSON bundle gives V3 a durable Supabase curriculum authority
-- without making assumptions about the historical normalized reference-table keys.
create table if not exists curriculum_bundles (
  curriculum_version text primary key,
  bundle jsonb not null,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table curriculum_bundles enable row level security;
drop policy if exists curriculum_bundles_read on curriculum_bundles;
create policy curriculum_bundles_read on curriculum_bundles for select to anon, authenticated using (active = true);
grant select on curriculum_bundles to anon, authenticated;

